import { useSyncExternalStore } from 'react';

// The colour theme, picked on the Settings page and kept per device. The colours themselves live in
// src/themes.css (generated by scripts/build-themes.mjs); this just sets <html data-theme="…">.
// index.html applies the saved theme before the app loads, so a reload doesn't flash the default.

export const THEMES = [
  { id: 'tavern', name: 'Tavern', description: 'Dark stone and candle gold. The original.', bar: '#1c1917' },
  { id: 'daylight', name: 'Daylight', description: 'Light and plain, for bright rooms.', bar: '#fafaf9' },
  { id: 'parchment', name: 'Parchment', description: 'Light cream paper with brown ink.', bar: '#f3ead7' },
  { id: 'midnight', name: 'Midnight', description: 'Deep blue-grey with cool cyan.', bar: '#0f172a' },
  { id: 'forest', name: 'Forest', description: 'Mossy dark green with lime.', bar: '#1d1f17' },
  { id: 'arcane', name: 'Arcane', description: 'Dusky purple with magenta glow.', bar: '#1f1820' },
] as const;

export type ThemeId = (typeof THEMES)[number]['id'];
export const DEFAULT_THEME: ThemeId = 'tavern';

/** Also read by the inline script in index.html; keep the two in step. */
const KEY = 'dm-combat-tracker:theme';

export function parseTheme(raw: string | null): ThemeId {
  return THEMES.find((t) => t.id === raw)?.id ?? DEFAULT_THEME;
}

function read(): ThemeId {
  try {
    return parseTheme(localStorage.getItem(KEY));
  } catch {
    return DEFAULT_THEME;
  }
}

function apply(id: ThemeId) {
  document.documentElement.dataset.theme = id;
  document.querySelector('meta[name="theme-color"]')?.setAttribute('content', THEMES.find((t) => t.id === id)!.bar);
}

let memory: ThemeId = read();
apply(memory);
const listeners = new Set<() => void>();

export function setTheme(id: ThemeId): void {
  memory = id;
  apply(id);
  try {
    localStorage.setItem(KEY, id);
  } catch {
    // Storage blocked: the theme just won't survive a reload.
  }
  for (const fn of listeners) fn();
}

function subscribe(fn: () => void) {
  listeners.add(fn);
  // Another tab changed it: follow along.
  const onStorage = (e: StorageEvent) => {
    if (e.key !== KEY) return;
    memory = parseTheme(e.newValue);
    apply(memory);
    fn();
  };
  window.addEventListener('storage', onStorage);
  return () => {
    listeners.delete(fn);
    window.removeEventListener('storage', onStorage);
  };
}

export function useTheme(): ThemeId {
  return useSyncExternalStore(subscribe, () => memory);
}
